_USER_SPACE_LOCK = _cos_threading.Lock()



_USER_SPACE_PATH = Path(str(next((p for p in Path(__file__).resolve().parents if (p / "frontend").exists()), Path(__file__).resolve().parents[2]) / "storage/temp/user_workspaces.json"))











def normalize_user_id(user_id: str | None = None) -> str:



    raw_id = (user_id or "guest").strip().lower()



    cleaned = _cos_re.sub(r"[^a-z0-9_@.-]+", "_", raw_id).strip("_")



    return cleaned or "guest"











def _default_personal_space(user_key: str) -> dict:



    return {



        "user_id": user_key,



        "display_name": user_key,



        "personal_notes": "",



        "favorite_presets": ["760", "1060"],



        "default_niche": "general",



        "saved_hooks": [],



        "recent_clips": [],



    }











def _load_user_spaces() -> dict:



    if not _USER_SPACE_PATH.exists():



        return {}



    try:



        data = _cos_json.loads(_USER_SPACE_PATH.read_text(encoding="utf-8"))



        return data if isinstance(data, dict) else {}



    except Exception:



        return {}











def _save_user_spaces(spaces: dict) -> None:



    _USER_SPACE_PATH.parent.mkdir(parents=True, exist_ok=True)



    tmp = _USER_SPACE_PATH.with_suffix(".json.tmp")



    tmp.write_text(_cos_json.dumps(spaces, indent=2), encoding="utf-8")



    tmp.replace(_USER_SPACE_PATH)











def get_user_personal_space(user_id: str | None = None, is_pro: bool = False) -> dict:



    user_key = normalize_user_id(user_id)



    with _USER_SPACE_LOCK:



        spaces = _load_user_spaces()



        existing = spaces.get(user_key)



        if not isinstance(existing, dict):



            existing = _default_personal_space(user_key)



            spaces[user_key] = existing



            _save_user_spaces(spaces)



        else:



            merged = _default_personal_space(user_key)



            merged.update(existing)



            existing = merged







    dna = get_clip_dna(user_key)



    quota = (



        get_free_clip_status(user_key, is_pro=is_pro)



        if "get_free_clip_status" in globals()



        else {"user_key": user_key, "limit": 2}



    )



    return {**existing, "clip_dna": dna, "quota": quota}











def update_user_personal_space(



    user_id: str | None = None,



    updates: dict | None = None,



    dna_updates: dict | None = None,



    is_pro: bool = False,



) -> dict:



    user_key = normalize_user_id(user_id)



    payload = updates if isinstance(updates, dict) else {}







    with _USER_SPACE_LOCK:



        spaces = _load_user_spaces()



        current = spaces.get(user_key)



        if not isinstance(current, dict):



            current = _default_personal_space(user_key)



        else:



            base = _default_personal_space(user_key)



            base.update(current)



            current = base







        for field in ("display_name", "personal_notes", "default_niche"):



            if field in payload and payload[field] is not None:



                current[field] = str(payload[field])







        if "favorite_presets" in payload and isinstance(payload["favorite_presets"], list):



            current["favorite_presets"] = [str(x) for x in payload["favorite_presets"][:10]]







        if "add_hook" in payload and payload["add_hook"]:



            hooks = list(current.get("saved_hooks") or [])



            hook_str = str(payload["add_hook"]).strip()



            if hook_str and hook_str not in hooks:



                hooks.insert(0, hook_str)



            current["saved_hooks"] = hooks[:25]







        if "add_recent_clip" in payload and isinstance(payload["add_recent_clip"], dict):



            recents = list(current.get("recent_clips") or [])



            recents.insert(0, payload["add_recent_clip"])



            current["recent_clips"] = recents[:30]







        spaces[user_key] = current



        _save_user_spaces(spaces)







    if dna_updates:



        save_clip_dna(user_key, dna_updates)







    return get_user_personal_space(user_key, is_pro=is_pro)











