def _dna_deep_merge(base: dict, override: dict) -> dict:



    merged = dict(base)



    for k, v in (override or {}).items():



        if isinstance(v, dict) and isinstance(merged.get(k), dict):



            merged[k] = _dna_deep_merge(merged[k], v)



        else:



            merged[k] = v



    return merged











def _load_clip_dna_store() -> dict:



    if not _CLIP_DNA_PATH.exists():



        return {}



    try:



        data = _cos_json.loads(_CLIP_DNA_PATH.read_text(encoding="utf-8"))



        return data if isinstance(data, dict) else {}



    except Exception:



        return {}











def _save_clip_dna_store(store: dict) -> None:



    _CLIP_DNA_PATH.parent.mkdir(parents=True, exist_ok=True)



    tmp = _CLIP_DNA_PATH.with_suffix(".json.tmp")



    tmp.write_text(_cos_json.dumps(store, indent=2), encoding="utf-8")



    tmp.replace(_CLIP_DNA_PATH)











def get_clip_dna(creator_id: str = "default") -> dict:



    key = normalize_user_id(creator_id) if creator_id else "default"



    with _CLIP_DNA_LOCK:



        store = _load_clip_dna_store()



        custom = store.get(key, {})



        return _dna_deep_merge(DEFAULT_CLIP_DNA, custom if isinstance(custom, dict) else {})











def save_clip_dna(creator_id: str = "default", updates: dict | None = None) -> dict:



    key = normalize_user_id(creator_id) if creator_id else "default"



    with _CLIP_DNA_LOCK:



        store = _load_clip_dna_store()



        current = store.get(key, {})



        if not isinstance(current, dict):



            current = {}



        next_profile = _dna_deep_merge(current, updates or {})



        store[key] = next_profile



        _save_clip_dna_store(store)



        return _dna_deep_merge(DEFAULT_CLIP_DNA, next_profile)











def apply_clip_dna_to_render_opts(



    creator_id: str = "default",



    graphics_preset: str | None = None,



    normalize_lufs: bool = True,



) -> dict:



    dna = get_clip_dna(creator_id=creator_id)



    colors = dna.get("video_colors", {})



    zoom_map = {"subtle": 1.05, "punchy": 1.15, "dynamic": 1.25}



    zoom_key = str(dna.get("zoom_intensity", "punchy")).strip().lower()



    return {



        "creator_id": normalize_user_id(creator_id),



        "graphics_preset": (graphics_preset or "760"),



        "normalize_lufs": bool(normalize_lufs),



        "zoom_scale": zoom_map.get(zoom_key, 1.15),



        "contrast": float(colors.get("contrast", 1.06)),



        "saturation": float(colors.get("saturation", 1.12)),



        "caption_style": dna.get("caption_style", {}),



        "sound_effects": dna.get("sound_effects", {}),



        "music": dna.get("music", {}),



        "intro_outro": dna.get("intro_outro", {}),



    }











def detect_dead_air_segments(



    media_path: str,



    noise_db: float = -35.0,



    min_silence_sec: float = 0.8,



    timeout_sec: int = 60,



) -> list[dict]:



    src_file = Path(media_path)



    if not src_file.exists() or not src_file.is_file():



        return []



    cmd = [



        "ffmpeg", "-hide_banner", "-nostats", "-i", str(src_file),



        "-af", f"silencedetect=noise={float(noise_db)}dB:d={max(0.1, float(min_silence_sec))}",



        "-f", "null", "-",



    ]



    try:



        proc = _cos_subprocess.run(cmd, capture_output=True, text=True, errors="replace", timeout=timeout_sec)



    except Exception:



        return []



    output_log = (proc.stderr or "") + "\n" + (proc.stdout or "")



    starts = [float(m) for m in _cos_re.findall(r"silence_start:\s*([0-9]+(?:\.[0-9]+)?)", output_log)]



    ends_and_durs = _cos_re.findall(



        r"silence_end:\s*([0-9]+(?:\.[0-9]+)?)\s*\|\s*silence_duration:\s*([0-9]+(?:\.[0-9]+)?)",



        output_log,



    )



    segments: list[dict] = []



    for idx, (end_str, dur_str) in enumerate(ends_and_durs):



        end_t = float(end_str)



        dur_t = float(dur_str)



        start_t = starts[idx] if idx < len(starts) else max(0.0, end_t - dur_t)



        segments.append({



            "start": round(max(0.0, start_t), 3),



            "end": round(max(start_t, end_t), 3),



            "duration": round(max(0.0, dur_t), 3),



        })



    return segments











def build_keep_segments_from_silence(



    silence_segments: list[dict],



    total_duration_sec: float,



    keep_pause_sec: float = 0.25,



    min_keep_chunk_sec: float = 0.2,



) -> list[dict]:



    duration = max(0.0, float(total_duration_sec))



    if duration <= 0.0:



        return []



    if not silence_segments:



        return [{"start": 0.0, "end": round(duration, 3)}]



    cushion = max(0.0, float(keep_pause_sec))



    sorted_sil = sorted(silence_segments, key=lambda s: (float(s.get("start", 0.0)), float(s.get("end", 0.0))))



    cut_intervals: list[tuple[float, float]] = []



    for seg in sorted_sil:



        s_start = max(0.0, float(seg.get("start", 0.0)))



        s_end = min(duration, float(seg.get("end", s_start)))



        cut_start = min(duration, s_start + cushion)



        cut_end = max(cut_start, s_end - cushion)



        if cut_end - cut_start >= 0.15:



            cut_intervals.append((cut_start, cut_end))



    if not cut_intervals:



        return [{"start": 0.0, "end": round(duration, 3)}]



    merged_cuts: list[tuple[float, float]] = []



    for c_start, c_end in cut_intervals:



        if not merged_cuts or c_start > merged_cuts[-1][1]:



            merged_cuts.append((c_start, c_end))



        else:



            prev_s, prev_e = merged_cuts[-1]



            merged_cuts[-1] = (prev_s, max(prev_e, c_end))



    keep_segments: list[dict] = []



    cursor = 0.0



    for c_start, c_end in merged_cuts:



        if c_start - cursor >= min_keep_chunk_sec:



            keep_segments.append({"start": round(cursor, 3), "end": round(c_start, 3)})



        cursor = max(cursor, c_end)



    if duration - cursor >= min_keep_chunk_sec:



        keep_segments.append({"start": round(cursor, 3), "end": round(duration, 3)})



    return keep_segments or [{"start": 0.0, "end": round(duration, 3)}]











def build_dead_air_trim_filter(keep_segments: list[dict], has_audio: bool = True) -> str:



    if not keep_segments:



        return ""



    parts: list[str] = []



    concat_inputs: list[str] = []



    for idx, seg in enumerate(keep_segments):



        s = max(0.0, float(seg["start"]))



        e = max(s + 0.05, float(seg["end"]))



        v_label = f"v{idx}"



        parts.append(f"[0:v]trim=start={s:.3f}:end={e:.3f},setpts=PTS-STARTPTS[{v_label}]")



        if has_audio:



            a_label = f"a{idx}"



            parts.append(f"[0:a]atrim=start={s:.3f}:end={e:.3f},asetpts=PTS-STARTPTS[{a_label}]")



            concat_inputs.append(f"[{v_label}][{a_label}]")



        else:



            concat_inputs.append(f"[{v_label}]")



    n = len(keep_segments)



    if has_audio:



        parts.append(f"{''.join(concat_inputs)}concat=n={n}:v=1:a=1[outv][outa]")



    else:



        parts.append(f"{''.join(concat_inputs)}concat=n={n}:v=1:a=0[outv]")



    return ";".join(parts)











def remove_dead_air_from_clip(



    input_path: str,



    output_path: str,



    total_duration_sec: float,



    noise_db: float = -35.0,



    min_silence_sec: float = 0.8,



    keep_pause_sec: float = 0.25,



    has_audio: bool = True,



) -> dict:



    src_file = Path(input_path)



    out_file = Path(output_path)



    if not src_file.exists():



        return {"trimmed": False, "output_path": str(out_file), "reason": "input_missing"}



    silences = detect_dead_air_segments(str(src_file), noise_db=noise_db, min_silence_sec=min_silence_sec)



    keep_segs = build_keep_segments_from_silence(silences, total_duration_sec=total_duration_sec, keep_pause_sec=keep_pause_sec)



    if len(keep_segs) <= 1 and len(silences) == 0:



        out_file.parent.mkdir(parents=True, exist_ok=True)



        shutil.copy2(src_file, out_file)



        return {"trimmed": False, "output_path": str(out_file), "silences_found": 0, "keep_segments": keep_segs}



    filter_graph = build_dead_air_trim_filter(keep_segs, has_audio=has_audio)



    out_file.parent.mkdir(parents=True, exist_ok=True)



    encoder = detect_fast_video_encoder() if "detect_fast_video_encoder" in globals() else "libx264"



    v_codec = [encoder] if encoder in ("h264_nvenc", "h264_qsv", "h264_amf") else ["libx264", "-preset", "veryfast", "-crf", "23"]



    cmd = ["ffmpeg", "-y", "-hide_banner", "-loglevel", "error", "-i", str(src_file), "-filter_complex", filter_graph, "-map", "[outv]"]



    if has_audio:



        cmd += ["-map", "[outa]", "-c:a", "aac", "-b:a", "192k"]



    cmd += ["-c:v", *v_codec, "-pix_fmt", "yuv420p", "-movflags", "+faststart", str(out_file)]



    try:



        proc = _cos_subprocess.run(cmd, capture_output=True, text=True, timeout=180)



    except Exception as exc:



        return {"trimmed": False, "output_path": str(out_file), "error": str(exc)}



    if proc.returncode != 0 or not out_file.exists():



        return {"trimmed": False, "output_path": str(out_file), "error": (proc.stderr or "")[-400:]}



    kept_total = round(sum(max(0.0, float(s["end"]) - float(s["start"])) for s in keep_segs), 3)



    return {"trimmed": True, "output_path": str(out_file), "silences_found": len(silences), "keep_segments": keep_segs, "trimmed_duration_sec": kept_total}











def build_voice_cleanup_filter(



    denoise_strength: str = "medium",



    highpass_hz: float = 85.0,



    clarity_boost_db: float = 3.0,



    normalize_lufs: bool = True,



) -> str:



    nf_map = {"light": -16.0, "medium": -22.0, "strong": -28.0}



    nf_val = nf_map.get(str(denoise_strength or "medium").strip().lower(), -22.0)



    hp = max(20.0, min(300.0, float(highpass_hz)))



    boost = max(0.0, min(8.0, float(clarity_boost_db)))



    filters = [f"highpass=f={hp:.1f}", f"afftdn=nf={nf_val:.1f}:tn=1"]



    if boost > 0.0:



        filters.append(f"equalizer=f=3200:t=q:w=1.2:g={boost:.1f}")



    if normalize_lufs:



        filters.append("loudnorm=I=-14.0:TP=-1.5:LRA=11.0")



    return ",".join(filters)











def cleanup_voice_in_media(



    input_path: str,



    output_path: str,



    denoise_strength: str = "medium",



    highpass_hz: float = 85.0,



    clarity_boost_db: float = 3.0,



    normalize_lufs: bool = True,



    video_copy: bool = True,



    timeout_sec: int = 180,



) -> dict:



    src_file = Path(input_path)



    out_file = Path(output_path)



    if not src_file.exists() or not src_file.is_file():



        return {"cleaned": False, "output_path": str(out_file), "reason": "input_missing"}



    af_chain = build_voice_cleanup_filter(denoise_strength=denoise_strength, highpass_hz=highpass_hz, clarity_boost_db=clarity_boost_db, normalize_lufs=normalize_lufs)



    out_file.parent.mkdir(parents=True, exist_ok=True)



    cmd = ["ffmpeg", "-y", "-hide_banner", "-loglevel", "error", "-i", str(src_file)]



    if video_copy:



        cmd += ["-c:v", "copy"]



    else:



        encoder = detect_fast_video_encoder() if "detect_fast_video_encoder" in globals() else "libx264"



        v_codec = [encoder] if encoder in ("h264_nvenc", "h264_qsv", "h264_amf") else ["libx264", "-preset", "veryfast", "-crf", "23"]



        cmd += ["-c:v", *v_codec, "-pix_fmt", "yuv420p"]



    cmd += ["-af", af_chain, "-c:a", "aac", "-b:a", "192k", str(out_file)]



    try:



        proc = _cos_subprocess.run(cmd, capture_output=True, text=True, timeout=timeout_sec)



    except Exception as exc:



        return {"cleaned": False, "output_path": str(out_file), "error": str(exc)}



    if proc.returncode != 0 or not out_file.exists():



        return {"cleaned": False, "output_path": str(out_file), "error": (proc.stderr or "")[-400:]}



    return {"cleaned": True, "output_path": str(out_file), "audio_filter": af_chain, "denoise_strength": denoise_strength}











