# SECTION 3: CLIP SELECTION & SERIES (COLLISIONS & AUTO-SERIES)



# =====================================================================



_AS_STOPWORDS = {



    "the", "and", "for", "with", "this", "that", "from", "into",



    "your", "you", "are", "was", "were", "have", "has", "had",



    "but", "not", "all", "can", "will", "just", "more", "about",



    "what", "when", "where", "why", "how", "clip", "part", "episode",



}











def _cc_normalize_text(text: str | None) -> str:



    return " ".join((text or "").lower().split()).strip()











def _cc_compute_time_overlap(s1: float, e1: float, s2: float, e2: float) -> dict:



    a_start, a_end = min(float(s1), float(e1)), max(float(s1), float(e1))



    b_start, b_end = min(float(s2), float(e2)), max(float(s2), float(e2))



    dur_a = max(0.0, a_end - a_start)



    dur_b = max(0.0, b_end - b_start)



    if dur_a <= 0.0 or dur_b <= 0.0:



        return {"overlap_sec": 0.0, "overlap_ratio": 0.0}



    overlap_sec = max(0.0, min(a_end, b_end) - max(a_start, b_start))



    min_dur = min(dur_a, dur_b)



    ratio = overlap_sec / min_dur if min_dur > 0.0 else 0.0



    return {"overlap_sec": round(overlap_sec, 3), "overlap_ratio": round(min(1.0, max(0.0, ratio)), 3)}











def detect_clip_collisions(



    candidate: dict,



    existing_clips: list[dict],



    time_overlap_threshold: float = 0.25,



    text_similarity_threshold: float = 0.82,



) -> dict:



    cand = candidate if isinstance(candidate, dict) else {}



    cand_id = str(cand.get("clip_id") or cand.get("id") or "candidate")



    cand_source = str(cand.get("source_id") or cand.get("source") or "").strip().lower()



    cand_start = float(cand.get("start_sec", cand.get("start", 0.0)) or 0.0)



    cand_end = float(cand.get("end_sec", cand.get("end", 0.0)) or 0.0)



    cand_text = _cc_normalize_text(cand.get("hook") or cand.get("transcript") or cand.get("title") or "")



    collisions: list[dict] = []



    for idx, existing in enumerate(existing_clips or []):



        if not isinstance(existing, dict):



            continue



        other_id = str(existing.get("clip_id") or existing.get("id") or f"clip_{idx + 1}")



        if cand_id and other_id == cand_id:



            continue



        other_source = str(existing.get("source_id") or existing.get("source") or "").strip().lower()



        same_source = (not cand_source and not other_source) or (cand_source == other_source and bool(cand_source))



        other_start = float(existing.get("start_sec", existing.get("start", 0.0)) or 0.0)



        other_end = float(existing.get("end_sec", existing.get("end", 0.0)) or 0.0)



        overlap_info = _cc_compute_time_overlap(cand_start, cand_end, other_start, other_end)



        overlap_ratio = overlap_info["overlap_ratio"]



        overlap_sec = overlap_info["overlap_sec"]



        other_text = _cc_normalize_text(existing.get("hook") or existing.get("transcript") or existing.get("title") or "")



        sim_ratio = round(_cos_SequenceMatcher(None, cand_text, other_text).ratio(), 3) if (cand_text and other_text) else 0.0



        reasons: list[str] = []



        severity = "none"



        if same_source and overlap_ratio >= float(time_overlap_threshold):



            reasons.append(f"time_overlap_{int(round(overlap_ratio * 100))}pct")



            severity = "high" if overlap_ratio >= 0.5 else "medium"



        if sim_ratio >= float(text_similarity_threshold):



            reasons.append(f"text_similarity_{int(round(sim_ratio * 100))}pct")



            if severity != "high":



                severity = "high" if sim_ratio >= 0.92 else "medium"



        if reasons:



            collisions.append({



                "matched_clip_id": other_id,



                "severity": severity,



                "reasons": reasons,



                "overlap_sec": overlap_sec,



                "overlap_ratio": overlap_ratio,



                "text_similarity": sim_ratio,



            })



    severity_rank = {"high": 2, "medium": 1, "none": 0}



    highest = "none"



    for item in collisions:



        if severity_rank.get(item["severity"], 0) > severity_rank.get(highest, 0):



            highest = item["severity"]



    return {"clip_id": cand_id, "has_collision": len(collisions) > 0, "highest_severity": highest, "collision_count": len(collisions), "collisions": collisions}











def _as_extract_tokens(moment: dict) -> set[str]:



    raw_parts = [



        str(moment.get("topic") or ""),



        str(moment.get("hook") or ""),



        str(moment.get("title") or ""),



        str(moment.get("transcript") or ""),



        " ".join(str(t) for t in (moment.get("tags") or []) if t),



    ]



    words = _cos_re.findall(r"[a-z0-9]{3,}", " ".join(raw_parts).lower())



    return {w for w in words if w not in _AS_STOPWORDS}











def format_series_episode_title(



    series_title: str,



    episode_number: int,



    moment_hook: str,



    style: str = "part",



) -> str:



    clean_series = " ".join((series_title or "Clip Series").split()).strip()



    clean_hook = " ".join((moment_hook or "Highlight").split()).strip()



    ep_num = max(1, int(episode_number))



    prefix = f"Ep. {ep_num}" if str(style or "part").strip().lower() == "ep" else f"Part {ep_num}"



    return f"{clean_series} | {prefix}: {clean_hook}"











def build_auto_series(



    moments: list[dict],



    series_title: str = "Highlight Series",



    max_episodes: int = 10,



    title_style: str = "part",



) -> dict:



    valid_moments = [m for m in (moments or []) if isinstance(m, dict)]



    if not valid_moments:



        return {"series_id": f"series_{_cos_uuid.uuid4().hex[:8]}", "series_title": series_title or "Highlight Series", "episode_count": 0, "episodes": []}



    token_sets = [_as_extract_tokens(m) for m in valid_moments]



    scored: list[tuple[float, float, int, dict]] = []



    for idx, m in enumerate(valid_moments):



        my_tokens = token_sets[idx]



        overlap_score = 0.0



        for jdx, other_tokens in enumerate(token_sets):



            if idx == jdx or not my_tokens or not other_tokens:



                continue



            union = len(my_tokens | other_tokens)



            if union > 0:



                overlap_score += len(my_tokens & other_tokens) / union



        start_sec = float(m.get("start_sec", m.get("start", idx * 10.0)) or 0.0)



        scored.append((overlap_score, start_sec, idx, m))



    cap = max(1, min(50, int(max_episodes or 10)))



    top_by_relevance = sorted(scored, key=lambda item: (-item[0], item[1], item[2]))[:cap]



    ordered = sorted(top_by_relevance, key=lambda item: (item[1], item[2]))



    total_eps = len(ordered)



    episodes: list[dict] = []



    for ep_idx, (_rel, _start, orig_idx, m) in enumerate(ordered, start=1):



        raw_id = str(m.get("clip_id") or m.get("id") or f"moment_{orig_idx + 1}")



        raw_hook = str(m.get("hook") or m.get("title") or m.get("topic") or f"Moment {ep_idx}").strip()



        s_sec = float(m.get("start_sec", m.get("start", 0.0)) or 0.0)



        e_sec = float(m.get("end_sec", m.get("end", s_sec)) or s_sec)



        episodes.append({



            "episode_number": ep_idx,



            "total_episodes": total_eps,



            "clip_id": raw_id,



            "start_sec": round(s_sec, 3),



            "end_sec": round(e_sec, 3),



            "hook": raw_hook,



            "episode_title": format_series_episode_title(series_title, ep_idx, raw_hook, title_style),



        })



    return {"series_id": f"series_{_cos_uuid.uuid4().hex[:8]}", "series_title": " ".join((series_title or "Highlight Series").split()).strip(), "episode_count": total_eps, "episodes": episodes}











# =====================================================================



# SECTION 4: TESTING & GROWTH COACH (A/B STUDIO & PERFORMANCE COACH)



# =====================================================================



_AB_LOCK = _cos_threading.Lock()



_AB_STORE_PATH = Path(str(next((p for p in Path(__file__).resolve().parents if (p / "frontend").exists()), Path(__file__).resolve().parents[2]) / "storage/temp/ab_tests.json"))



_VIRALITY_DISCLAIMER = (



    "AI can score hook clarity and predict retention potential, "



    "but actual virality cannot be guaranteed."



)











def _load_ab_store() -> dict:



    if not _AB_STORE_PATH.exists():



        return {}



    try:



        data = _cos_json.loads(_AB_STORE_PATH.read_text(encoding="utf-8"))



        return data if isinstance(data, dict) else {}



    except Exception:



        return {}











def _save_ab_store(store: dict) -> None:



    _AB_STORE_PATH.parent.mkdir(parents=True, exist_ok=True)



    tmp = _AB_STORE_PATH.with_suffix(".json.tmp")



    tmp.write_text(_cos_json.dumps(store, indent=2), encoding="utf-8")



    tmp.replace(_AB_STORE_PATH)











def _default_variant_templates(base_hook: str, niche: str, num_variants: int = 3) -> list[dict]:



    seed = " ".join((base_hook or "").split()).strip() or "Nobody expected what happened next"



    short_seed = seed[:54].rstrip(" .,!?:;")



    niche_label = (niche or "general").strip().title()



    templates = [



        {"variant_id": "A", "label": "Direct Hook + Bold Captions", "hook": f"{short_seed} | here is why it matters.", "opening_style": "immediate_payoff", "caption_style": {"casing": "UPPERCASE", "position": "center", "highlight_mode": "active_word"}},



        {"variant_id": "B", "label": "Curiosity Gap + Clean Captions", "hook": f"Wait until you see what happens right after: {short_seed[:38]}", "opening_style": "curiosity_gap", "caption_style": {"casing": "Sentence case", "position": "bottom", "highlight_mode": "phrase_box"}},



        {"variant_id": "C", "label": "Contrarian Angle + High-Contrast Captions", "hook": f"Most {niche_label} clips get this backwards | {short_seed[:36]}", "opening_style": "contrarian_claim", "caption_style": {"casing": "UPPERCASE", "position": "top", "highlight_mode": "underline_pop"}},



    ]



    return templates[: (2 if int(num_variants) == 2 else 3)]











def create_ab_test_study(



    user_id: str = "default",



    clip_id: str = "clip_1",



    base_hook: str = "",



    niche: str = "general",



    num_variants: int = 3,



    custom_variants: list[dict] | None = None,



) -> dict:



    u_key = normalize_user_id(user_id)



    study_id = f"ab_{_cos_uuid.uuid4().hex[:8]}"



    raw_templates = custom_variants if isinstance(custom_variants, list) and len(custom_variants) >= 2 else _default_variant_templates(base_hook=base_hook, niche=niche, num_variants=num_variants)



    variants = []



    for idx, item in enumerate(raw_templates[:3]):



        vid = str(item.get("variant_id") or chr(65 + idx)).upper()



        variants.append({



            "variant_id": vid,



            "label": str(item.get("label") or f"Variant {vid}"),



            "hook": str(item.get("hook") or base_hook or f"Hook {vid}").strip(),



            "opening_style": str(item.get("opening_style") or "standard"),



            "caption_style": dict(item.get("caption_style") or {}),



            "metrics": {"views": 0, "retention_pct": 0.0, "avg_watch_sec": 0.0, "likes": 0, "shares": 0, "comments": 0},



        })



    study = {"study_id": study_id, "user_id": u_key, "clip_id": clip_id, "niche": (niche or "general").strip().lower(), "variants": variants, "virality_note": _VIRALITY_DISCLAIMER}



    with _AB_LOCK:



        store = _load_ab_store()



        user_studies = store.get(u_key, [])



        if not isinstance(user_studies, list):



            user_studies = []



        user_studies.insert(0, study)



        store[u_key] = user_studies[:50]



        _save_ab_store(store)



    return study











def record_ab_variant_metrics(



    user_id: str,



    study_id: str,



    variant_id: str,



    views: int = 0,



    retention_pct: float = 0.0,



    avg_watch_sec: float = 0.0,



    likes: int = 0,



    shares: int = 0,



    comments: int = 0,



) -> dict:



    u_key = normalize_user_id(user_id)



    v_key = str(variant_id or "").strip().upper()



    with _AB_LOCK:



        store = _load_ab_store()



        user_studies = store.get(u_key, [])



        for study in user_studies:



            if study.get("study_id") == study_id:



                for variant in study.get("variants", []):



                    if str(variant.get("variant_id", "")).upper() == v_key:



                        variant["metrics"] = {



                            "views": max(0, int(views)),



                            "retention_pct": max(0.0, min(100.0, float(retention_pct))),



                            "avg_watch_sec": max(0.0, float(avg_watch_sec)),



                            "likes": max(0, int(likes)),



                            "shares": max(0, int(shares)),



                            "comments": max(0, int(comments)),



                        }



                        _save_ab_store(store)



                        return compare_ab_test_study(u_key, study_id)



        raise ValueError(f"Study {study_id} or variant {variant_id} not found for user {u_key}")











def compare_ab_test_study(user_id: str, study_id: str) -> dict:



    u_key = normalize_user_id(user_id)



    with _AB_LOCK:



        store = _load_ab_store()



        user_studies = store.get(u_key, [])



        target = next((s for s in user_studies if s.get("study_id") == study_id), None)



        if not target:



            raise ValueError(f"Study {study_id} not found for user {u_key}")



    ranked = []



    for v in target.get("variants", []):



        m = v.get("metrics", {})



        views = max(0, int(m.get("views", 0)))



        retention = max(0.0, float(m.get("retention_pct", 0.0)))



        shares = max(0, int(m.get("shares", 0)))



        likes = max(0, int(m.get("likes", 0)))



        comments = max(0, int(m.get("comments", 0)))



        engagement_rate_pct = ((likes + shares * 2 + comments * 2) / views * 100.0) if views > 0 else 0.0



        score = round(retention * 0.65 + min(engagement_rate_pct * 4.0, 35.0), 2)



        ranked.append({



            "variant_id": v.get("variant_id"),



            "label": v.get("label"),



            "hook": v.get("hook"),



            "opening_style": v.get("opening_style"),



            "caption_style": v.get("caption_style"),



            "metrics": m,



            "engagement_rate_pct": round(engagement_rate_pct, 2),



            "performance_score": score,



        })



    ranked.sort(key=lambda item: item["performance_score"], reverse=True)



    has_data = any(item["metrics"].get("views", 0) > 0 or item["metrics"].get("retention_pct", 0.0) > 0 for item in ranked)



    leader = ranked[0] if (ranked and has_data) else None



    return {"study_id": study_id, "user_id": u_key, "clip_id": target.get("clip_id"), "leader_variant_id": leader["variant_id"] if leader else None, "ranked_variants": ranked, "virality_note": _VIRALITY_DISCLAIMER}











def coach_creator_performance(



    clips: list[dict],



    user_id: str = "default",



    apply_to_clip_dna: bool = False,



) -> dict:



    u_key = normalize_user_id(user_id)



    rows = [c for c in (clips or []) if isinstance(c, dict)]



    if not rows:



        return {



            "user_id": u_key,



            "clips_analyzed": 0,



            "averages": {"views": 0, "retention_pct": 0.0, "share_rate_pct": 0.0, "engagement_rate_pct": 0.0},



            "recommendations": [{"area": "baseline", "priority": "medium", "action": "Publish at least 3 clips and log views, retention %, and shares to unlock personalized coaching."}],



            "dna_updated": False,



        }



    total_views = 0



    retention_sum = 0.0



    share_rate_sum = 0.0



    engagement_rate_sum = 0.0



    long_clip_count = 0



    high_retention_count = 0



    for c in rows:



        views = max(0, int(c.get("views", 0) or 0))



        retention = max(0.0, min(100.0, float(c.get("retention_pct", 0.0) or 0.0)))



        likes = max(0, int(c.get("likes", 0) or 0))



        shares = max(0, int(c.get("shares", 0) or 0))



        comments = max(0, int(c.get("comments", 0) or 0))



        dur = max(0.0, float(c.get("duration_sec", 0.0) or 0.0))



        total_views += views



        retention_sum += retention



        if dur > 45.0:



            long_clip_count += 1



        if retention >= 72.0:



            high_retention_count += 1



        if views > 0:



            share_rate_sum += (shares / views) * 100.0



            engagement_rate_sum += ((likes + shares * 2 + comments * 2) / views) * 100.0



    n = len(rows)



    avg_views = round(total_views / n, 1)



    avg_retention = round(retention_sum / n, 2)



    avg_share_rate = round(share_rate_sum / n, 2)



    avg_engagement_rate = round(engagement_rate_sum / n, 2)



    recommendations: list[dict] = []



    suggested_dna_updates: dict = {}



    if avg_retention < 55.0:



        recommendations.append({"area": "opening_hook_and_pacing", "priority": "high", "action": "Cut the first 1-2 seconds of setup, trim pauses above 0.6s with Dead-Air Remover, and test 2-3 hook variants in Viral A/B Testing Studio."})



        suggested_dna_updates["zoom_intensity"] = "dynamic"



    elif avg_retention < 70.0:



        recommendations.append({"area": "mid_clip_momentum", "priority": "medium", "action": "Keep punchy zooms and highlight caption emphasis active through the middle of the clip so viewers stay until the payoff."})



        suggested_dna_updates["zoom_intensity"] = "punchy"



    if avg_share_rate < 1.5:



        recommendations.append({"area": "shareability_and_series", "priority": "medium", "action": "Lead with a sharper curiosity gap or contrarian claim, and group related clips into numbered episodes with Auto-Series Creator."})



    if long_clip_count > n / 2.0 and avg_retention < 65.0:



        recommendations.append({"area": "clip_length", "priority": "medium", "action": "Aim for tighter 20-35 second cuts instead of longer clips when retention dips past the halfway mark."})



    if high_retention_count > 0:



        recommendations.append({"area": "winning_pattern", "priority": "low", "action": f"{high_retention_count} of {n} clips hit 72%+ retention | keep those hook structures and caption styles as your baseline."})



    if not recommendations:



        recommendations.append({"area": "consistency", "priority": "low", "action": "Retention and engagement look healthy | keep your current pacing consistent and test subtle caption or title variations."})



    dna_updated = False



    if apply_to_clip_dna and suggested_dna_updates:



        save_clip_dna(u_key, suggested_dna_updates)



        dna_updated = True



    return {



        "user_id": u_key,



        "clips_analyzed": n,



        "averages": {"views": avg_views, "retention_pct": avg_retention, "share_rate_pct": avg_share_rate, "engagement_rate_pct": avg_engagement_rate},



        "suggested_dna_updates": suggested_dna_updates,



        "dna_updated": dna_updated,



        "recommendations": recommendations,



    }



def prepare_render_with_dna_collision_and_quota(

    user_id: str | None = None,

    clip_id: str = "clip_1",

    source_id: str = "",

    start_sec: float = 0.0,

    end_sec: float = 0.0,

    hook: str = "",

    graphics_preset: str | None = None,

    normalize_lufs: bool = True,

    is_pro: bool = False,

    allow_collision: bool = False,

    consume_quota: bool = True,

) -> dict:

    """Runs Clip DNA resolution, collision check, and quota consumption in safe order."""

    u_key = normalize_user_id(user_id) if "normalize_user_id" in globals() else ((user_id or "guest").strip().lower() or "guest")

    space = get_user_personal_space(u_key, is_pro=is_pro) if "get_user_personal_space" in globals() else {"recent_clips": []}

    dna_opts = (

        apply_clip_dna_to_render_opts(u_key, graphics_preset=graphics_preset, normalize_lufs=normalize_lufs)

        if "apply_clip_dna_to_render_opts" in globals()

        else {"graphics_preset": (graphics_preset or "760"), "normalize_lufs": bool(normalize_lufs)}

    )



    candidate = {

        "clip_id": clip_id,

        "source_id": source_id,

        "start_sec": float(start_sec or 0.0),

        "end_sec": float(end_sec or 0.0),

        "hook": hook or "",

    }

    existing_clips = space.get("recent_clips") if isinstance(space, dict) else []

    collision = (

        detect_clip_collisions(candidate, existing_clips if isinstance(existing_clips, list) else [])

        if "detect_clip_collisions" in globals()

        else {"has_collision": False, "highest_severity": "none", "collisions": []}

    )



    if collision.get("has_collision") and collision.get("highest_severity") == "high" and not allow_collision:

        return {

            "allowed": False,

            "reason": "clip_collision_detected",

            "user_id": u_key,

            "dna_opts": dna_opts,

            "collision": collision,

        }



    quota_result = None

    if consume_quota and not is_pro and "consume_free_clip_quota" in globals():

        quota_result = consume_free_clip_quota(u_key)

        if isinstance(quota_result, dict) and quota_result.get("allowed") is False:

            return {

                "allowed": False,

                "reason": "free_clip_quota_exceeded",

                "user_id": u_key,

                "dna_opts": dna_opts,

                "collision": collision,

                "quota": quota_result,

            }



    return {

        "allowed": True,

        "user_id": u_key,

        "dna_opts": dna_opts,

        "collision": collision,

        "quota": quota_result,

    }

